@section('content')<div class="page"><div class="eyebrow">12 / PELANGGAN</div><h1>Buat reservasi</h1><p class="subtitle">{{$resto->nama}} · {{$resto->alamat}}, {{$resto->kota}}</p><form method="POST" action="{{route('customer.reserve.store',$resto)}}" class="row g-4">@csrf<div class="col-lg-8"><div class="panel mb-4"><h5 class="mb-3">Jadwal kunjungan</h5><div class="row g-3"><div class="col-md-4"><label class="field-label">Tanggal</label><input class="form-control" type="date" name="tanggal" min="{{now()->toDateString()}}" value="{{old('tanggal',now()->toDateString())}}" required></div><div class="col-md-4"><label class="field-label">Jam</label><input class="form-control" type="time" name="jam" value="{{old('jam','19:00')}}" required></div><div class="col-md-4"><label class="field-label">Jumlah orang</label><input class="form-control" type="number" name="jumlah_orang" min="1" max="100" value="{{old('jumlah_orang',2)}}" required></div><div class="col-12"><label class="field-label">Catatan (opsional)</label><textarea class="form-control" name="catatan" rows="2" placeholder="Contoh: kursi dekat jendela">{{old('catatan')}}</textarea></div></div></div><div class="panel"><h5 class="mb-1">Pilih menu</h5><p class="subtitle">Minimal total menu Rp50.000. Masukkan kuantitas yang diinginkan.</p>@foreach($resto->menus as $menu)<div class="row align-items-center py-3" style="border-bottom:1px solid var(--line)"><div class="col"><strong>{{$menu->nama}}</strong><div class="subtitle small">{{$menu->kategori}} · Rp{{number_format($menu->harga,0,',','.')}}</div></div><div class="col-auto"><input class="form-control menu-qty" type="number" min="0" max="50" name="menu[{{$menu->id}}]" value="{{old('menu.'.$menu->id,0)}}" data-price="{{$menu->harga}}" style="width:85px" aria-label="Jumlah {{$menu->nama}}"></div></div>@endforeach</div></div><div class="col-lg-4"><div class="panel" style="background:#f5f0fb;position:sticky;top:100px"><h5>Ringkasan pesanan</h5><p class="subtitle">DP sebesar {{$resto->dp_persen}}% dari total menu.</p><div class="d-flex justify-content-between py-2"><span>Total menu</span><strong id="total">Rp0</strong></div><div class="d-flex justify-content-between py-2"><span>DP yang dibayar</span><strong id="dp">Rp0</strong></div><div class="d-flex justify-content-between py-2"><span>Sisa pembayaran</span><strong id="sisa">Rp0</strong></div><div class="small subtitle my-3">Setelah reservasi dibuat, unggah bukti transfer dari halaman Reservasi Saya. Pemilik resto akan memverifikasi DP Anda.</div><button class="btn btn-purple w-100" type="submit">Buat reservasi <i class="bi bi-arrow-right ms-2"></i></button></div></div></form></div>@push('scripts')<script>const dpRate={{$resto->dp_persen}};function rupiah(n){return 'Rp'+Math.round(n).toLocaleString('id-ID')}function refreshTotal(){let total=0;document.querySelectorAll('.menu-qty').forEach(el=>total+=(parseInt(el.value||0)*parseInt(el.dataset.price||0)));const dp=Math.round(total*dpRate/100);document.getElementById('total').textContent=rupiah(total);document.getElementById('dp').textContent=rupiah(dp);document.getElementById('sisa').textContent=rupiah(total-dp)}document.querySelectorAll('.menu-qty').forEach(el=>el.addEventListener('input',refreshTotal));refreshTotal();</script>@endpush @endsection
